module input_buffer (rst, clk,input_stream,output_buffer);

input clk;
input rst;
input input_stream;
output reg [7:0] output_buffer;

// wire input_stream;
// reg [7:0] output_buffer;
reg [6:0] temp;


always @(posedge clk)
	begin
	if (rst) begin
		output_buffer=8'b11111111;
		temp=7'b1111111;
	end	else begin
		temp[6:0]=output_buffer[7:1];
		output_buffer[6:0]=temp[6:0];
		output_buffer[7:7]=input_stream;
		end
	end

