module counter (rst, clk,count_over);

input clk;
input rst;
output count_over;

reg count_over;
reg[2:0] count_value;



always @(posedge clk) begin
	if (rst)
		begin
		count_over=0;
		count_value=3'b000;
	end
	else if (count_value==3'b111)
		begin
		count_over=1;
		count_value=3'b000;
		end
	else 
		begin
		count_over=0;
		count_value=count_value+1;
		end
	end

endmodule

/* 
 *
 * This module checks if a valid pack_start code is received
 * Only when `start' is set to 1
 * On getting valid pack_start_code make `stop'=1 
 *
