module fsm_for_pack_start(rst, one_byte,start,enable,stop);

//input clk;
input rst;
input [7:0] one_byte;
input start;
input enable;
output reg stop;

//wire clk;
// wire[7:0] one_byte;
// wire start;
// wire enable;
// reg stop;

reg[2:0] state;



always @(posedge enable) begin
	if (rst) begin
		stop=0;
		state=0;
	end
	else if (start==1) 
	begin
	case (state)
		0:	begin
			case (one_byte)
			8'b00000000: state=1;
			default	   : state=0;	
			endcase
			end

		1:	begin
			case (one_byte)
			8'b00000000: state=2;
			default	   : state=0;	
			endcase
			end  

		2:	begin
			case (one_byte)
			8'b00000001: state=3;
			8'b00000000: state=1;
			default	   : state=0;	
			endcase
			end

		3:	begin
			case (one_byte)
			8'b01011101: begin
				     stop=1;
			             state=0;
				     end
			8'b00000000: state=1;
			default	   : state=0;
			endcase  
			end



	endcase
	end
	else stop=0;

	end

