reg[2:0] count;




//always
  // begin
    //  if (start==1)
	// stop=0;
   //end // always begin

always @(posedge enable) begin
if (rst)
	begin
	stop=0;
	scr_reg=0;
	mux_rate_reg=0;
	count=3'b000;

/*...check maybe change these initial values later....*/
	end
else if (start==1)
	begin
	case (count)
		3'b000: begin
			scr_reg[7:0]=one_byte[7:0];
			count=count+1;
			end
		3'b001: begin
			scr_reg[15:8]=one_byte[7:0];
			count=count+1;
			end
		3'b010: begin
			scr_reg[23:16]=one_byte[7:0];
			count=count+1;
			end
                3'b011: begin
			scr_reg[31:24]=one_byte[7:0];
			count=count+1;
			end
		3'b100: begin
			scr_reg[39:32]=one_byte[7:0];
			count=count+1;
			end
