					stop=1;
				     end // case: 8'b00000011

			8'b10000011: begin
			             Mem[1]=stream_temp1;
			             stop=1;
			             end

			8'b01000011: begin
			             Mem[2]=stream_temp1;
			             stop=1;
			             end
			8'b11000011: begin
			             Mem[3]=stream_temp1;
			             stop=1;
			             end
			8'b00000111: begin
